const crypto = require('crypto');
const req = $input.first().json;
const given = String((req.headers || {})['x-ryvo-cockpit-secret'] || '');
const want  = String($env.COCKPIT_SEND_SECRET || '');
let authed = false;
if (want && given.length === want.length) {
  authed = crypto.timingSafeEqual(Buffer.from(given), Buffer.from(want));
}
return [{ json: { authed, leadId: String((req.body || {}).leadId || '') } }];

// ---------------------------------------------------------------------------
// Language detection is RENDERED FROM src/language.js at generation time, not
// retyped. Lesson 15: two copies of a rule diverge and the stale one keeps
// reporting confidently. The generator raises if it cannot read the file.
// ---------------------------------------------------------------------------
const HARD_MARKERS = [
  { lang: 'pt', rx: /[ãõ]/, weight: 6 },          // não, mão, então, opções
  { lang: 'pt', rx: /ç/, weight: 5 },             // preço, começar
  { lang: 'es', rx: /ñ/, weight: 6 },             // mañana, año, señor
  { lang: 'es', rx: /[¿¡]/, weight: 6 },          // inverted punctuation
];

// Function words and greetings. Deliberately excludes anything the three share
// (que, para, no, si/sim, por favor, esta) -- a shared word is not evidence.
// Function words. Only DISCRIMINATING tokens: anything the languages share
// (que, para, no, casa, como, por favor) is not evidence and is excluded.
// The pt/es minimal pairs do most of the work here -- com/con, uma/una,
// quando/cuando, muito/mucho -- because those two are the pair that actually
// gets confused.
const WORD_MARKERS = {
  pt: ['nao', 'obrigado', 'obrigada', 'ola', 'voce', 'gostaria', 'queria',
       'muito', 'estou', 'tenho', 'tem', 'quero', 'bom dia', 'boa tarde',
       'boa noite', 'feira', 'imovel', 'imoveis', 'moradia', 'preciso',
       'gostava', 'entao', 'onde', 'com', 'uma', 'um', 'quando', 'quanto',
       'qual', 'mais', 'na', 'nas', 'dos', 'das', 'ate', 'posso', 'pode',
       'procuro', 'visitar', 'marcar', 'falar', 'pessoa', 'afinal', 'mudar'],
  es: ['hola', 'gracias', 'quisiera', 'usted', 'tambien', 'buenos dias',
       'buenas tardes', 'buenas noches', 'vivienda', 'piso', 'necesito',
       'busco', 'con', 'una', 'cuando', 'cuanto', 'donde', 'ahora', 'manana',
       'el', 'los', 'las', 'muy', 'mucho', 'estoy', 'tengo', 'puedo',
       'hablar', 'jueves', 'viernes', 'quiero'],
  en: ['the', 'and', 'you', 'are', 'is', 'would', 'like', 'hello', 'hi',
       'thanks', 'thank', 'please', 'can', 'i', 'im', 'looking', 'house',
       'flat', 'apartment', 'available', 'viewing', 'week', 'time', 'do',
       'have', 'see', 'come', 'speak', 'person', 'anything', 'something'],
};

const SUPPORTED = ['pt', 'en', 'es'];

// detectLanguage(text) -> {lang: 'pt'|'en'|'es'|null, scores, confident}
// Returns null when the evidence is thin or the top two are close. Callers
// must treat null as "use the configured default", never as a language.
function detectLanguage(text) {
  const raw = String(text || '');
  const out = (lang, scores, confident) => ({ lang, scores, confident });
  if (!raw.trim()) return out(null, { pt: 0, en: 0, es: 0 }, false);

  const lower = raw.toLowerCase();
  const scores = { pt: 0, en: 0, es: 0 };

  for (const m of HARD_MARKERS) {
    if (m.rx.test(lower)) scores[m.lang] += m.weight;
  }

  // Normalise for word matching so "voce"/"você" and "manana"/"mañana" both
  // land, having already banked the diacritic evidence above.
  const flat = ' ' + lower.normalize('NFD').replace(/[̀-ͯ]/g, '')
                          .replace(/[^a-z0-9']+/g, ' ').trim() + ' ';
  for (const lang of SUPPORTED) {
    for (const w of WORD_MARKERS[lang]) {
      const needle = w.includes(' ') ? w : ' ' + w + ' ';
      if (flat.includes(needle)) scores[lang] += 2;
    }
  }

  const ranked = SUPPORTED.slice().sort((a, b) => scores[b] - scores[a]);
  const top = ranked[0], second = ranked[1];
  // A single weak hit decides nothing, and a near-tie between pt and es is the
  // case most likely to be wrong. Both fall back rather than guess.
  // Two ways to be sure, and they cover different shapes of message:
  //   - unopposed: any evidence at all for exactly one language, none for the
  //     others. "Ola, procuro casa em Cascais" is short but unambiguous.
  //   - contested: enough evidence AND a clear margin. This is the pt/es case,
  //     where both score and the winner has to actually win.
  // Everything else falls back to the configured default rather than guessing.
  const unopposed = scores[top] >= 2 && scores[second] === 0;
  const contested = scores[top] >= 4 && (scores[top] - scores[second]) >= 4;
  const confident = unopposed || contested;
  return out(confident ? top : null, scores, confident);
}

const lr = $('LoadLead').first().json;
const mr = $input.first().json;
const lead = (Array.isArray(lr.body) ? lr.body : [])[0] || null;
const msgs = Array.isArray(mr.body) ? mr.body : [];

if (!lead) return [{ json: { ok: false, error: 'lead_not_found' } }];

const client = lead.clients || {};
const cfg = ((client.client_automations || [])[0] || {}).config || {};

// The lead's OWN words decide the language -- never our own outbound text,
// which is what the assistant already chose and would make this circular.
const leadText = msgs.filter(m => m.direction === 'inbound').map(m => m.body || '').join(' \n');
const det = detectLanguage(leadText);
const fallback = String(cfg.default_language || (client.locale || 'pt-PT').slice(0,2) || 'pt');
const language = det.lang || fallback;

const esc = (lead.qualification || {}).escalated || {};
const reasons = Array.isArray(esc.reasons) ? esc.reasons : (esc.reason ? [esc.reason] : []);

const transcript = msgs.map(m => (m.direction === 'inbound' ? 'LEAD: ' : 'ASSISTANT: ') + String(m.body || '')).join('\n');

return [{ json: {
  ok: true,
  leadId: lead.id,
  language,
  languageConfident: det.confident,
  fallbackLanguage: fallback,
  reasons,
  // The key the Concierge reads, with its own legacy fallback.
  handoff: (cfg.system_messages || {}).handoff
           || (cfg.handoff_note ? { [String(cfg.default_language || 'pt')]: cfg.handoff_note } : {}),
  agentName: cfg.agent_name || 'the assistant',
  agencyName: cfg.agency_name || client.name || '',
  transcript,
  leadName: lead.full_name || '',
} }];

const p = $input.first().json;
if (!p.ok) return [{ json: p }];

// The prompt ASKS. The cockpit's guards DECIDE. Every line below is written
// on the assumption that the model will occasionally ignore it -- which is
// why none of these rules rests on the wording alone.
const system = [
  'You draft a WhatsApp reply for a human estate agent to review. You are NOT talking to the lead.',
  'A human reads every word before anything is sent. Never address the reader as the lead.',
  '',
  'HARD RULES:',
  '1. Never propose, confirm or mention any date or time. You have no calendar and no slots.',
  '2. Never state a price, a discount, or any figure the lead has not already given you.',
  '3. Never negotiate, and never take a position on price or terms.',
  '4. Never invent property details, availability or stock.',
  '5. Say only what is true from the conversation. If you do not know, say a colleague will confirm.',
  '',
  'Write ONE short paragraph, at most 45 words, in ' + p.language + '.',
  'Warm, plain, professional. No greeting boilerplate beyond a short opener. No sign-off.',
  'Return the reply text only, with no preamble and no quotation marks.',
].join('\n');

const user = [
  'Agency: ' + p.agencyName,
  'Assistant name: ' + p.agentName,
  'Lead: ' + p.leadName,
  'Why it was handed to a human: ' + (p.reasons.join(', ') || 'unknown'),
  '',
  'Conversation so far:',
  p.transcript || '(no messages stored)',
  '',
  'Draft the reply.',
].join('\n');

return [{ json: { ...p, systemPrompt: system, userPrompt: user } }];

const p = $('BuildPrompt').first().json;
const res = $input.first().json;
const ok = res.statusCode >= 200 && res.statusCode < 300;
const body = res.body || {};
let text = '';
if (ok && Array.isArray(body.content)) {
  text = body.content.filter(b => b.type === 'text').map(b => b.text).join('').trim();
}
// The cockpit applies the §7 guards itself, in unit-tested TypeScript. This
// endpoint returns the raw draft and the context needed to judge it -- it does
// not get to decide what is safe. Two independent checks, one of them testable.
return [{ json: {
  ok: true,
  draft: text,
  modelOk: ok,
  error: ok ? null : ('claude_' + res.statusCode),
  language: p.language,
  languageConfident: p.languageConfident,
  fallbackLanguage: p.fallbackLanguage,
  reasons: p.reasons,
  handoff: p.handoff,
  transcript: p.transcript,
} }];
